  if (!STATUS.includes(o.suggested_status)) throw new Error('bad suggested_status');
  if (!SEVERITY.includes(o.suggested_severity)) throw new Error('bad suggested_severity');
  if (typeof o.suspicious_instructions !== 'boolean') throw new Error('bad suspicious_instructions');
  return {
    source_fact: cut(o.source_fact, 300),
    inference: cut(o.inference, 300),
    // " | " joins the gaps in the sheet, so a gap cannot contain "|".
    proof_gaps: o.proof_gaps.slice(0, 5).map((g) => cut(g.replace(/\|/g, '/'), 160)),
    suggested_status: o.suggested_status,
    suggested_severity: o.suggested_severity,
    reason: cut(o.reason, 300),
    suspicious_instructions: o.suspicious_instructions,
  };
}

