let ai = null;
let error = null;
try {
  const text = extractText(res);
  let parsed;
  try { parsed = JSON.parse(text); } catch (e) { throw new Error('response is not valid JSON'); }
  ai = validate(parsed);
} catch (e) {
  error = `${PROVIDER}: ${e.message}`;
}

return { json: {
  ...finding,
  _ai_ok: ai !== null,
  _ai: ai,
  _ai_provider: ai ? PROVIDER : 'none',
  _ai_errors: [...(finding._ai_errors ?? []), ...(error ? [error] : [])],
} };

// Flow 1 · finalize AI (Run Once for Each Item)
// Turns the AI result into the ai_* columns of `findings`.
// Arrives from three places: secrets (never sent), Gemini OK, or after the Groq attempt.
// A deterministic pattern check runs on the PR author's text no matter what the model said.

const f = $input.item.json;
const isSecret = f.category === 'secrets';
const ai = isSecret ? null : (f._ai ?? null);

// Text that addresses an AI or a reviewer, or tries to break out of the delimiters.
const INJECTION = [
  /\b(ignore|disregard|forget|override)\b[^\n]{0,40}\b(previous|prior|above|earlier|all|any|these|those|your)\b[^\n]{0,20}\b(instructions?|rules?|prompts?|guidelines?)/i,
  /\b(system|developer)\s+(prompt|message|instructions?)\b/i,
  /\b(you are|act as|as an?)\s+(now\s+)?(an?\s+)?(ai|assistant|language model|llm|chatbot|gpt|gemini|claude|reviewer|triage)\b/i,
  /\b(ai|llm|model|assistant|reviewer|triage|scanner)\b[^\n]{0,40}\b(mark|classify|label|treat|report|rate)\b/i,
  /\b(mark|classify|label|treat|report|rate)\s+(this|it|the finding|this finding)\s+as\s+(a\s+)?(false[\s_-]?positive|safe|benign|harmless|info|low)\b/i,
  /<\s*\/?\s*untrusted_finding/i,
  /\b(ignora|olvida)\b[^\n]{0,30}\binstrucciones\b/i,
];
const authorText = [f.file, f.rule, f.message, f.snippet].map((v) => String(v ?? '')).join('\n');
const patternHit = INJECTION.some((re) => re.test(authorText));
const modelHit = Boolean(ai && ai.suspicious_instructions);
const flags = [patternHit && 'pattern', modelHit && 'model'].filter(Boolean);

// Severity floor: with suspected injection the AI may raise the severity but never put it
// below what the scanner's own rule said (the PR author cannot change that with a comment).
const SEV_RANK = ['info', 'low', 'medium', 'high', 'critical'];
const FLOOR = { error: 'high', warning: 'medium', note: 'low' };
let severity = ai ? ai.suggested_severity : '';
let raisedFrom = null;
if (ai && flags.length) {
  const floor = FLOOR[f.severity] ?? 'medium';
  if (SEV_RANK.indexOf(severity) < SEV_RANK.indexOf(floor)) { raisedFrom = severity; severity = floor; }
}

let reason;
if (isSecret) reason = 'Not sent to AI: secrets findings never leave the pipeline.';
else if (!ai) reason = `AI failed: ${(f._ai_errors ?? []).join('; ')}`.slice(0, 300);
else reason = ai.reason;
// Why the fallback was used: Gemini's error, kept even when Groq answered.
if (ai && f._ai_provider === 'groq') {
  const geminiError = (f._ai_errors ?? []).find((e) => e.startsWith('gemini')) ?? 'gemini: unknown error';
  reason = `[fallback: ${geminiError.slice(0, 120)}] ${reason}`;
}
// This prefix goes first: the email marks the finding in red when ai_reason starts with it.
if (flags.length) {
  const raised = raisedFrom ? `; severity raised from ${raisedFrom}` : '';
  reason = `[injection suspected: ${flags.join(', ')}${raised}] ${reason}`;
}

// Keep the sheet columns only; internal fields start with "_".
const row = {};
for (const [k, v] of Object.entries(f)) if (!k.startsWith('_')) row[k] = v;

Object.assign(row, {
  ai_provider: ai ? f._ai_provider : 'none',
  // Suspected injection always goes to a human with "needs_evidence", whatever the model said.
  ai_status: ai ? (flags.length ? 'needs_evidence' : ai.suggested_status) : '',
  ai_severity: severity,
  ai_source_fact: ai ? ai.source_fact : '',
  ai_inference: ai ? ai.inference : '',
  ai_proof_gaps: ai ? ai.proof_gaps.join(' | ') : '',
  ai_reason: reason,
});

// Pace the free tiers: 5 s after a Gemini call, 20 s when Groq was tried (8K tokens per minute).
const triedGroq = (f._ai_errors ?? []).some((e) => e.startsWith('gemini')) || f._ai_provider === 'groq';
const waitSeconds = isSecret ? 0 : (triedGroq ? 20 : 5);

return { json: { ...row, _ai_failed: !isSecret && !ai, _injection: flags.join(','), _wait_s: waitSeconds } };

// Flow 1 · list pending (Run Once for All Items)
// One item per finding that still needs a human decision (new ones, plus known ones
// not yet decided), with the expiry for its decision link. "sign links" adds the HMAC.
// If nothing is pending, one empty item keeps the branch going so the run is still logged.

const TTL_DAYS = 3;
const exp = Math.floor(Date.now() / 1000) + TTL_DAYS * 24 * 3600;

const pending = new Set();
for (const { json } of $('classify').all()) {
  if (json._target === 'new') pending.add(String(json.id));
  if (json._target === 'known' && json._pending !== false) pending.add(String(json.id));
}

const items = [...pending].map((fid) => ({ json: { fid, exp } }));
return items.length ? items : [{ json: { fid: '', exp: 0, _none: true } }];

// Flow 1 · build email
// One email per PR, only with findings that still need a human decision:
// the new ones plus known ones that nobody has decided yet.
// File paths, messages and rule ids come from code the PR author controls,
// so every value is HTML-escaped before it goes into the email.

const run = $('classify').all().find((i) => i.json._target === 'run').json;
const payload = $('Webhook').first().json.body;
const pr = payload.pr;

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit';
const FORM_URL = 'https://YOUR_N8N_HOST/form/decide';

// Signed decision links from "sign links": fid + exp + HMAC (flow 2 checks all three).
const links = new Map();
for (const { json } of $('sign links').all()) {
  if (json.fid && json.sig) {
    links.set(String(json.fid), `${FORM_URL}?fid=${encodeURIComponent(json.fid)}&exp=${json.exp}&sig=${json.sig}`);
  }
}
const linkOf = (id) => links.get(String(id)) ?? '';
const SEV_RANK = { error: 0, warning: 1, note: 2 };
const SEV_NAME = ['error', 'warning', 'note', 'unknown'];

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const shortRule = (r) => String(r ?? '').split('.').pop();
const short = (s, n) => { const t = String(s ?? ''); return t.length > n ? `${t.slice(0, n - 1)}…` : t; };

// AI columns: new findings from this run's AI step, known ones from the sheet.
const aiById = new Map();
for (const { json } of $('Get findings').all()) if (json.id) aiById.set(String(json.id), json);
let aiRun = [];
try { aiRun = $('AI results').all().map((i) => i.json); } catch (e) { /* no new findings in this run */ }
for (const r of aiRun) aiById.set(String(r.id), r);
const aiFailures = aiRun.filter((r) => r._ai_failed).length;
const aiOf = (id) => {
  const r = aiById.get(String(id)) ?? {};
  return { status: r.ai_status || '-', severity: r.ai_severity || '-', provider: r.ai_provider || 'none',
    reason: r.ai_reason || '', injection: String(r.ai_reason || '').startsWith('[injection suspected') };
};

// Which findings are new, and which known ones are still undecided.
const state = new Map();
for (const { json } of $('classify').all()) {
  if (json._target === 'new') state.set(json.id, { isNew: true, pending: true });
  if (json._target === 'known') state.set(json.id, { isNew: false, pending: json._pending !== false });
}

// Group pending findings by file:line, so two rules on one line are one decision.
const groups = new Map();
for (const f of payload.findings) {
  const s = state.get(f.id);
  if (!s || !s.pending) continue;
  const key = `${f.file}:${f.line}`;
  if (!groups.has(key)) {
    groups.set(key, { file: f.file, line: f.line, module: f.module, level: f.dvwa_level,
      origin: 'preexisting', isNew: false, sev: 3, items: [] });
  }
  const g = groups.get(key);
  g.items.push(f);
  g.isNew = g.isNew || s.isNew;
  g.sev = Math.min(g.sev, SEV_RANK[f.severity] ?? 3);
  if (f.introduced_by_pr) g.origin = 'pr';
}

const list = [...groups.values()].sort((a, b) =>
  a.sev - b.sev || String(a.file).localeCompare(String(b.file)) || a.line - b.line);
const newCount = list.filter((g) => g.isNew).length;
const prUrl = `https://github.com/${pr.repo}/pull/${pr.number}`;

const subject = `[dvwa-ai-triage] PR #${pr.number}: ${list.length} to review (${newCount} new)`;

// Plain-text part.
const textLines = list.map((g) => {
  const tools = g.items.map((f) => `${f.tool} ${shortRule(f.rule)} [${f.id}]`).join(', ');
  const where = g.module ? `${g.module}/${g.level ?? '-'}` : '-';
  const ai = g.items.map((f) => {
    const a = aiOf(f.id);
    return `    AI [${f.id}]: ${a.status} / ${a.severity} (${a.provider}) ${short(a.reason, 200)}`
      + (linkOf(f.id) ? `\n    Decide [${f.id}]: ${linkOf(f.id)}` : '');
  });
  return [`- [${SEV_NAME[g.sev]}] ${g.file}:${g.line} | ${tools} | ${where} | ${g.origin}${g.isNew ? ' | NEW' : ''}`,
    ...ai].join('\n');
});
const text = [
  `PR #${pr.number} in ${pr.repo}: ${prUrl}`,
  `${list.length} location(s) need a decision (${newCount} new).`,
  'Evidence: static analysis only, no runtime validation. Every item is a candidate, not a confirmed vulnerability.',
  '',
  ...textLines,
  '',
  'AI triage: suggestions only (Gemini, Groq as fallback); a human makes every decision. Decision links expire in 3 days.',
  ...(aiFailures ? [`AI failures in this run: ${aiFailures}.`] : []),
  `Records: ${SHEET_URL}`,
  `Run: ${pr.run_url}`,
].join('\n');

// HTML part.
const td = 'style="padding:6px 8px;border-bottom:1px solid #ddd;vertical-align:top"';
const rows = list.map((g) => {
  const tools = g.items.map((f) =>
    `${esc(f.tool)} <code>${esc(shortRule(f.rule))}</code><br><small>${esc(f.id)}</small>`).join('<br>');
  const where = g.module ? `${esc(g.module)} / ${esc(g.level ?? '-')}` : '-';
  const ai = g.items.map((f) => {
    const a = aiOf(f.id);
    const warn = a.injection ? '<span style="color:#b00020"><b>Injection suspected</b></span><br>' : '';
    const decide = linkOf(f.id)
      ? `<br><a href="${esc(linkOf(f.id))}" style="display:inline-block;margin-top:4px;padding:4px 10px;background:#1a73e8;color:#fff;text-decoration:none;border-radius:4px">Decide ${esc(f.id)}</a>`
      : '';
    return `${warn}<b>${esc(a.status)}</b> · ${esc(a.severity)} <small>(${esc(a.provider)})</small>`
      + `<br><small>${esc(short(a.reason, 220))}</small>${decide}`;
  }).join('<br>');
  return `<tr><td ${td}>${esc(SEV_NAME[g.sev])}</td>`
    + `<td ${td}><code>${esc(g.file)}:${esc(g.line)}</code></td>`
    + `<td ${td}>${tools}</td><td ${td}>${where}</td>`
    + `<td ${td}>${esc(g.origin)}${g.isNew ? ' <b>NEW</b>' : ''}</td>`
    + `<td ${td} width="320">${ai}</td></tr>`;
}).join('');
const th = 'style="text-align:left;padding:6px 8px;border-bottom:2px solid #333"';
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
<p><b><a href="${esc(prUrl)}">PR #${esc(pr.number)}</a></b> in ${esc(pr.repo)}: ${list.length} location(s) need a decision (${newCount} new).</p>
<p style="color:#555">Evidence: static analysis only, no runtime validation. Every item is a candidate, not a confirmed vulnerability.</p>
<table style="border-collapse:collapse"><tr><th ${th}>Severity</th><th ${th}>Location</th><th ${th}>Tool / rule</th><th ${th}>Module / level</th><th ${th}>Origin</th><th ${th}>AI suggestion</th></tr>${rows}</table>
<p style="color:#555">AI triage: suggestions only (Gemini, Groq as fallback); a human makes every decision. Decision links expire in 3 days.${aiFailures ? ` AI failures in this run: ${aiFailures}.` : ''}</p>
<p><a href="${esc(SHEET_URL)}">Records</a> · <a href="${esc(pr.run_url)}">Run</a></p>
</div>`;

return [{ json: { ...run, ai_failures: aiFailures, email_sent: false, _send: list.length > 0,
  _subject: subject, _text: text, _html: html } }];

// Flow 1 · finalize run
// Records whether the email went out. Send Email returns `accepted` on success;
// its error output carries only `error`.
const row = { ...$('build email').first().json };
const res = $input.first().json;
row.email_sent = Array.isArray(res.accepted) && res.accepted.length > 0;
return [{ json: row }];
